//! Experiment 5 (throwaway), step 2 of the chain: activate `indochina` ("Burma", the union polygon of the stage-1
//! regions.esf) and the new land region `sumatra` ("Sumatra") as playable regions and stage every changed campaign file
//! under F:/NTW2/work/exp5/out/data (nothing is written into the game folder).
//!
//! Inputs: stage-1 regions.esf (F:/NTW2/work/exp5/stage1/regions.esf), pristine poi.esf / trade_routes.esf of exp4's
//! backup, exp3's TGAs / pathfinding / sea_grids (only read for their theatre rectangle; both are regenerated by the
//! later steps), the pre-Burma startpos and pack of exp4's backup.
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail, ensure};
use serde_json::{Value, json};

use kgc_port_editor::db::{self, Cell, Schema, Table};
use kgc_port_editor::esf;
use kgc_port_editor::map::MapArtifacts;
use kgc_port_editor::model::{Project, RegionActivation, Rules};
use kgc_port_editor::pack::{self, Pack};
use kgc_port_editor::regionmap::apply;
use kgc_port_editor::regionmap::regions::RegionData;
use kgc_port_editor::regionmap::startpos_split;

const GAME_DATA: &str = "F:/NTW2/Napoleon Total War/data";
const DEFAULT_ROOT: &str = "F:/NTW2/work/exp5";
const EXP3_MAP: &str = "F:/NTW2/work/exp3/out/data/campaign_maps/nap_world";
const EXP4_BACKUP: &str = "F:/NTW2/work/exp4/backup/data";
const VANILLA_MAP: &str = "F:/NTW2/work/exp1/backup/campaign_maps/nap_world";
const ASSETS: &str = "F:/NTW2/kgc_port_editor/assets";

const BURMA: &str = "indochina";
const SUMATRA: &str = "sumatra";
const BURMA_COLOUR: [u8; 3] = [210, 80, 190];
const THEATRE_LOOKUP: &str = "india_lookup.tga";
const LOC_MEMBER: &str = "text\\localisation.loc";

fn copy(from: &Path, to: &Path) -> Result<()> {
    if let Some(dir) = to.parent() {
        fs::create_dir_all(dir)?;
    }
    fs::copy(from, to).with_context(|| format!("copy {} -> {}", from.display(), to.display()))?;
    Ok(())
}

fn copy_dir_filtered(from: &Path, to: &Path, skip: &dyn Fn(&str) -> bool) -> Result<usize> {
    if to.exists() {
        fs::remove_dir_all(to)?;
    }
    fs::create_dir_all(to)?;
    let mut n = 0;
    for e in fs::read_dir(from)? {
        let e = e?;
        let name = e.file_name().to_string_lossy().to_string();
        if e.file_type()?.is_file() && !skip(&name) {
            copy(&e.path(), &to.join(&name))?;
            n += 1;
        }
    }
    Ok(n)
}

/// Palette (BGR -> RGB) of an 8-bit colour-mapped TGA.
fn tga_palette(d: &[u8]) -> Result<Vec<[u8; 3]>> {
    let at = 18 + d[0] as usize;
    let first = u16::from_le_bytes([d[3], d[4]]) as usize;
    let count = u16::from_le_bytes([d[5], d[6]]) as usize;
    ensure!(d[1] == 1 && d[7] == 24 && first == 0, "not a 24-bit colour-mapped TGA");
    Ok((0..count).map(|i| [d[at + 3 * i + 2], d[at + 3 * i + 1], d[at + 3 * i]]).collect())
}

/// The colour with the largest distance to every colour in `used` (grid search), channels kept off the extremes.
fn pick_colour(used: &[[u8; 3]]) -> [u8; 3] {
    let dist = |a: [u8; 3], b: [u8; 3]| -> i64 { (0..3).map(|k| (a[k] as i64 - b[k] as i64).pow(2)).sum() };
    let mut best = ([0u8; 3], -1i64);
    for r in (45..=210u16).step_by(5) {
        for g in (45..=210u16).step_by(5) {
            for b in (45..=210u16).step_by(5) {
                let c = [r as u8, g as u8, b as u8];
                let m = used.iter().map(|&u| dist(c, u)).min().unwrap_or(i64::MAX);
                if m > best.1 {
                    best = (c, m);
                }
            }
        }
    }
    best.0
}

/// Decode a DB member and check that it re-encodes to the same bytes (so a rewrite only changes what we touch).
fn decode_checked(name: &str, bytes: &[u8], schema: &Schema) -> Result<Table> {
    let t = db::decode(name, bytes, schema)?;
    ensure!(db::encode(&t)? == bytes, "{name} does not round-trip byte-exact");
    Ok(t)
}

fn row_json(t: &Table, i: usize) -> Result<Value> {
    Ok(t.json_rows()?.swap_remove(i))
}

fn cell_row(t: &Table, row: &Value) -> Result<Vec<Cell>> {
    t.fields
        .iter()
        .map(|f| Cell::from_json(&f.ty, row.get(&f.name).with_context(|| format!("missing {}", f.name))?))
        .collect()
}

/// Point of the region's polygon with the largest distance to its outline (pole of inaccessibility; coarse grid then
/// repeated refinement around the best cell).
fn pole_of_inaccessibility(rd: &RegionData, ri: usize) -> Result<([f64; 2], f64)> {
    let (mut lo, mut hi) = ([f64::MAX; 2], [f64::MIN; 2]);
    for a in &rd.regions[ri].areas {
        for o in a.outlines.iter().filter(|o| o.outer) {
            for &v in &o.ring {
                let p = rd.v(v);
                for k in 0..2 {
                    lo[k] = lo[k].min(p[k]);
                    hi[k] = hi[k].max(p[k]);
                }
            }
        }
    }
    ensure!(lo[0] <= hi[0], "region {} has no outline", rd.regions[ri].key);
    let score = |p: [f64; 2]| if rd.in_region(ri, p) { rd.distance_to_region(ri, p) } else { -1.0 };
    let mut best = ([0.0; 2], -1.0f64);
    let mut half = 0.0f64;
    let n = 60;
    let step = [(hi[0] - lo[0]) / n as f64, (hi[1] - lo[1]) / n as f64];
    for i in 0..=n {
        for j in 0..=n {
            let p = [lo[0] + step[0] * i as f64, lo[1] + step[1] * j as f64];
            let s = score(p);
            if s > best.1 {
                best = (p, s);
            }
        }
    }
    half = half.max(step[0].max(step[1]));
    for _ in 0..40 {
        let c = best.0;
        let h = half;
        for i in -10..=10 {
            for j in -10..=10 {
                let p = [c[0] + h * i as f64 / 10.0, c[1] + h * j as f64 / 10.0];
                let s = score(p);
                if s > best.1 {
                    best = (p, s);
                }
            }
        }
        half *= 0.6;
    }
    ensure!(best.1 > 0.0, "no interior point found");
    Ok(best)
}

fn main() -> Result<()> {
    // EXP5_VARIANT=B: bisect build, Burma union only (no sumatra) under F:/NTW2/work/exp5/variantB
    let variant_b = std::env::var("EXP5_VARIANT").is_ok_and(|v| v.eq_ignore_ascii_case("B"));
    let with_sumatra = !variant_b;
    let keys: Vec<&str> = if with_sumatra { vec![BURMA, SUMATRA] } else { vec![BURMA] };
    let default_root = if variant_b { format!("{DEFAULT_ROOT}/variantB") } else { DEFAULT_ROOT.to_string() };
    let root = std::env::var("EXP5_ROOT").unwrap_or(default_root);
    let out_data = PathBuf::from(format!("{root}/out/data"));
    let out_map = out_data.join("campaign_maps/nap_world");
    let work = PathBuf::from(format!("{root}/driver_work/map"));
    let exp3 = PathBuf::from(EXP3_MAP);
    let backup = PathBuf::from(EXP4_BACKUP);
    let backup_map = backup.join("campaign_maps/nap_world");
    let game_map = PathBuf::from(GAME_DATA).join("campaign_maps/nap_world");
    let regions_in = PathBuf::from(
        std::env::var("EXP5_REGIONS").unwrap_or_else(|_| format!("{root}/stage1/regions.esf")),
    );
    ensure!(regions_in.exists(), "stage-1 regions.esf {} does not exist", regions_in.display());
    let mut notes: Vec<String> = Vec::new();

    // ---------------------------------------------------------------- 1. stage the map files (scratch dir)
    if work.exists() {
        fs::remove_dir_all(&work)?;
    }
    fs::create_dir_all(&work)?;
    copy(&regions_in, &work.join("regions.esf"))?;
    copy(&exp3.join("pathfinding.esf"), &work.join("pathfinding.esf"))?;
    copy(&exp3.join("sea_grids.esf"), &work.join("sea_grids.esf"))?;
    for name in ["poi.esf", "trade_routes.esf"] {
        copy(&backup_map.join(name), &work.join(name))?;
    }
    copy(&exp3.join(THEATRE_LOOKUP), &work.join(THEATRE_LOOKUP))?;
    let border_src = if Path::new(VANILLA_MAP).join("display/borders").exists() {
        PathBuf::from(VANILLA_MAP).join("display/borders")
    } else {
        game_map.join("display/borders")
    };
    let skip = |n: &str| (n.starts_with("indochina") || n.starts_with("sumatra")) && n.ends_with(".rigid_spline");
    let nb = copy_dir_filtered(&border_src, &work.join("display/borders"), &skip)?;
    println!("staged {} in {} ({nb} border files copied from {})", regions_in.display(), work.display(), border_src.display());

    // ---------------------------------------------------------------- 2. rules and the two activations
    let assets = kgc_port_editor::local_assets::ensure(
        &kgc_port_editor::pipeline::default_workspace(Path::new(ASSETS)),
        Path::new(ASSETS),
        &|message| println!("{message}"),
    )?;
    let mut rules = Rules::load(&assets.join("rules"))?;
    let schema = Schema::load(&assets.join("rules/schema_nap.ron"))?;
    let pack_in = Pack::open(&backup.join("nap_world.pack"))?;
    let regions_member = "db\\regions_tables\\nap_world";
    let settle_member = "db\\campaign_map_settlements_tables\\nap_world";
    let areas_member = "db\\campaign_map_playable_areas_tables\\nap_world";
    let regions_old = decode_checked("regions_tables", &pack_in.read(regions_member)?, &schema)?;
    let settle_old = decode_checked("campaign_map_settlements_tables", &pack_in.read(settle_member)?, &schema)?;
    let areas_old = decode_checked("campaign_map_playable_areas_tables", &pack_in.read(areas_member)?, &schema)?;

    let rd0 = RegionData::parse(&esf::read(&fs::read(work.join("regions.esf"))?)?.root)?;
    let burma_i = rd0.index(BURMA)?;
    let sumatra_i = if with_sumatra { rd0.index(SUMATRA)? } else { usize::MAX };
    if with_sumatra {
        ensure!(sumatra_i == rd0.regions.len() - 1, "sumatra is region {sumatra_i} of {}, it must be the last", rd0.regions.len());
    } else {
        ensure!(rd0.index(SUMATRA).is_err(), "variant B input must not contain sumatra");
    }
    let passable_of = |i: usize| -> Vec<usize> {
        rd0.regions[i].areas.iter().enumerate().filter(|(_, a)| a.passable).map(|(i, _)| i).collect()
    };
    println!(
        "stage-1: {} regions; indochina index {burma_i} areas {} passable {:?}",
        rd0.regions.len(),
        rd0.regions[burma_i].areas.len(),
        passable_of(burma_i)
    );
    ensure!(passable_of(burma_i) == [0], "indochina passable areas are {:?}, expected [0]", passable_of(burma_i));
    if with_sumatra {
        println!("sumatra index {sumatra_i} areas {} passable {:?}", rd0.regions[sumatra_i].areas.len(), passable_of(sumatra_i));
        ensure!(passable_of(sumatra_i) == [0], "sumatra passable areas are {:?}, expected [0]", passable_of(sumatra_i));
    }

    // settlement points
    let burma_centre = [683.9f32, 119.8f32];
    let (pole, pole_d) = if with_sumatra { pole_of_inaccessibility(&rd0, sumatra_i)? } else { ([0.0; 2], 0.0) };
    let sumatra_centre: [f32; 2] = match std::env::var("EXP5_SUMATRA_CENTER") {
        Ok(s) => {
            let v: Vec<f32> = s.split(',').map(|x| x.trim().parse()).collect::<Result<_, _>>()?;
            ensure!(v.len() == 2, "EXP5_SUMATRA_CENTER must be x,y");
            [v[0], v[1]]
        }
        Err(_) => [pole[0] as f32, pole[1] as f32],
    };
    let mut centres = vec![(BURMA, burma_centre, burma_i)];
    if with_sumatra {
        centres.push((SUMATRA, sumatra_centre, sumatra_i));
    }
    for (key, c, ri) in centres {
        let p = [c[0] as f64, c[1] as f64];
        let d = rd0.distance_to_region(ri, p);
        ensure!(rd0.area_at(ri, p) == Some(0), "{key}: the centre {c:?} is not in area 0");
        ensure!(d >= 3.0, "{key}: the centre {c:?} is only {d:.2} from the outline");
        println!("{key}: settlement centre {c:?}, {d:.2} from the outline");
    }
    if with_sumatra {
        println!("sumatra pole of inaccessibility {pole:?} (distance {pole_d:.2})");
    }

    // lookup colours: farthest from every colour of the theatre's palette, regions_tables and the rules
    let mut used = tga_palette(&fs::read(work.join(THEATRE_LOOKUP))?)?;
    for row in regions_old.json_rows()? {
        used.push([row["r"].as_u64().unwrap_or(0) as u8, row["g"].as_u64().unwrap_or(0) as u8, row["b"].as_u64().unwrap_or(0) as u8]);
    }
    for (_, r) in rules.regions.as_object().context("regions rules")? {
        if let Some(c) = r.get("lookup_rgb").and_then(Value::as_array) {
            if c.len() == 3 {
                used.push([c[0].as_u64().unwrap_or(0) as u8, c[1].as_u64().unwrap_or(0) as u8, c[2].as_u64().unwrap_or(0) as u8]);
            }
        }
    }
    ensure!(!used.contains(&BURMA_COLOUR), "the Burma colour {BURMA_COLOUR:?} is in use already");
    used.push(BURMA_COLOUR);
    let sumatra_colour = if with_sumatra { pick_colour(&used) } else { [0, 0, 0] };
    ensure!(!with_sumatra || !used.contains(&sumatra_colour), "colour clash");
    println!("lookup colours: Burma {BURMA_COLOUR:?}, Sumatra {sumatra_colour:?} (checked against {} colours)", used.len());

    let mut activations = vec![
        RegionActivation {
            key: BURMA.into(),
            donor: "bengal".into(),
            name: "Burma".into(),
            settlement: "rangoon".into(),
            settlement_name: "Rangoon".into(),
            center: burma_centre,
            colour: BURMA_COLOUR,
            ..Default::default()
        },
    ];
    if with_sumatra {
        activations.push(RegionActivation {
            key: SUMATRA.into(),
            donor: "ceylon".into(),
            name: "Sumatra".into(),
            settlement: "aceh".into(),
            settlement_name: "Aceh".into(),
            center: sumatra_centre,
            colour: sumatra_colour,
            ..Default::default()
        });
    }
    let mut project = Project::default();
    project.activations = activations.clone();
    rules.apply_project(&project)?;
    for a in &activations {
        let r = &rules.regions[&a.key];
        println!(
            "rules.regions[{}]: owner {} continent {} theatre {} rebel {:?} capital {}",
            a.key, r["owner"], r["continent"], r["theatre"], r["rebel_name"], r["capital_settlement"]
        );
    }

    let mut map = MapArtifacts {
        slot_mapping: json!({ "regions": {} }),
        trade_nodes: Value::Null,
        db_rows: BTreeMap::from([
            (
                "campaign_map_playable_areas_tables".to_string(),
                json!({ "table": "campaign_map_playable_areas_tables", "version": areas_old.version, "rows": areas_old.json_rows()? }),
            ),
            (
                "campaign_map_settlements_tables".to_string(),
                json!({ "table": "campaign_map_settlements_tables", "version": settle_old.version, "rows": settle_old.json_rows()? }),
            ),
        ]),
        loc_rows: Vec::new(),
    };

    // ---------------------------------------------------------------- 3. map: apply the activations
    // pathfinding.esf and sea_grids.esf are regenerated by the following steps, so their per-region checks are off
    let (applied, stats) = apply::apply_activations_staged(&work, &activations, &rules, &mut map, false)?;
    ensure!(applied.len() == keys.len(), "expected {} applied activations", keys.len());
    let after = RegionData::parse(&esf::read(&fs::read(work.join("regions.esf"))?)?.root)?;
    ensure!(rd0.regions.len() == after.regions.len() && rd0.vertices == after.vertices, "regions.esf geometry changed");
    for (i, (a, b)) in rd0.regions.iter().zip(&after.regions).enumerate() {
        ensure!(a.key == b.key && a.kind == b.kind && a.areas.len() == b.areas.len(), "region {i} changed shape");
        for (x, y) in a.areas.iter().zip(&b.areas) {
            ensure!(
                x.passable == y.passable
                    && x.adjoining_id == y.adjoining_id
                    && x.impassable_id == y.impassable_id
                    && x.island_id == y.island_id
                    && x.faces == y.faces
                    && x.outlines.len() == y.outlines.len(),
                "region {} area flags/faces changed",
                a.key
            );
        }
        if i != burma_i && !(with_sumatra && i == sumatra_i) {
            ensure!(a.tail == b.tail && a.settlement.is_some() == b.settlement.is_some(), "region {} changed", a.key);
        }
    }
    for (ap, st) in applied.iter().zip(&stats) {
        ensure!(after.regions[ap.index].settlement.is_some(), "{} has no settlement after apply", ap.key);
        println!(
            "regions.esf: {} index {} tail {} theatre {} neighbours {:?}; poi {:?}; trade node {} ({} routes); lookup {} painted {} px (palette {}); borders {:?}",
            ap.key, ap.index, st.tail, ap.theatre, ap.neighbours, st.poi, st.trade_node, st.trade_routes, st.lookup_file,
            st.lookup.painted, st.lookup.palette_index, st.border_files_written
        );
        ensure!(st.border_files_removed.is_empty(), "{}: unexpected border removals {:?}", ap.key, st.border_files_removed);
    }

    // ---------------------------------------------------------------- 4. start position (pre-Burma)
    let startpos_in = backup.join("campaigns/wld_napoleon/startpos.esf");
    let startpos_out = out_data.join("campaigns/wld_napoleon/startpos.esf");
    let mut sp = esf::read(&fs::read(&startpos_in)?)?;
    for (act, ap) in activations.iter().zip(&applied) {
        let spec = if act.key == BURMA {
            startpos_split::new_region_for_activation(&sp.root, act, ap, &rules)?
        } else {
            startpos_split::new_region_for_carve(&sp.root, &after, act, ap, &rules)?
        };
        let before = sp.root.clone();
        let report = startpos_split::add_region(&mut sp.root, &spec)?;
        let bytes = esf::write(&sp)?;
        let back = esf::read(&bytes)?;
        let problems = startpos_split::check(&before, &back.root, &spec)?;
        if !problems.is_empty() {
            bail!("start position check for {} found {} problems:\n  {}", act.key, problems.len(), problems.join("\n  "));
        }
        println!(
            "startpos {}: check() empty; region id {} settlement id {} owner {} settlement index {} CAI ids {:?} neighbours {:?} (existing_cai {})",
            act.key, report.region_id, report.settlement_id, report.owner, report.settlement_index, report.cai_range, spec.neighbours, spec.existing_cai
        );
        for n in &report.notes {
            println!("  note: {n}");
        }
    }
    let sp_bytes = esf::write(&sp)?;
    if let Some(dir) = startpos_out.parent() {
        fs::create_dir_all(dir)?;
    }
    fs::write(&startpos_out, &sp_bytes)?;

    // ---------------------------------------------------------------- 5. pack (pre-Burma)
    let mut members: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    for e in &pack_in.entries {
        members.insert(e.name.clone(), pack_in.read_entry(e)?);
    }
    let probe = PathBuf::from(&root).join("driver_work/probe.pack");
    pack::write_pack(&probe, &members, pack_in.type_)?;
    ensure!(fs::read(&probe)? == fs::read(&pack_in.path)?, "write_pack of the unmodified members differs from the backup pack");
    fs::remove_file(&probe)?;

    // regions_tables: an existing row of the key is replaced in place; a missing one is cloned from the donor's row
    let mut regions_new = regions_old.clone();
    let key_col = regions_new.column("key")?;
    for act in &activations {
        let rule = &rules.regions[&act.key];
        let existing = regions_new.rows.iter().position(|r| r[key_col].as_str() == Some(act.key.as_str()));
        let donor_at = regions_new
            .rows
            .iter()
            .position(|r| r[key_col].as_str() == Some(act.donor.as_str()))
            .with_context(|| format!("regions_tables has no donor row {}", act.donor))?;
        let mut row = row_json(&regions_new, existing.unwrap_or(donor_at))?;
        let old_row = row.clone();
        row["key"] = json!(act.key);
        row["continent"] = json!(rule["continent"].as_str().context("rule continent")?);
        row["r"] = json!(act.colour[0]);
        row["g"] = json!(act.colour[1]);
        row["b"] = json!(act.colour[2]);
        row["battle_name"] = json!(act.settlement_name);
        let cells = cell_row(&regions_new, &row)?;
        match existing {
            Some(at) => {
                println!("regions_tables[{}]: {old_row} -> {row}", act.key);
                regions_new.rows[at] = cells;
            }
            None => {
                let keys: Vec<&str> = regions_new.rows.iter().filter_map(|r| r[key_col].as_str()).collect();
                let sorted = keys.windows(2).all(|w| w[0] <= w[1]);
                let at = if sorted {
                    regions_new.rows.iter().position(|r| r[key_col].as_str().is_some_and(|k| k > act.key.as_str())).unwrap_or(regions_new.rows.len())
                } else {
                    regions_new.rows.len()
                };
                println!("regions_tables: NEW row {} at {at} (table sorted: {sorted}) = {row} (template {old_row})", act.key);
                regions_new.rows.insert(at, cells);
            }
        }
    }
    members.insert(regions_member.to_string(), db::encode(&regions_new)?);

    // campaign_map_settlements_tables
    let rows = map.db_rows["campaign_map_settlements_tables"]["rows"].as_array().context("settlement rows")?.clone();
    let mut settle_new = settle_old.clone();
    settle_new.rows = rows.iter().map(|r| cell_row(&settle_old, r)).collect::<Result<_>>()?;
    let id_col = settle_old.column("settlement_id")?;
    let old_ids: Vec<&str> = settle_old.rows.iter().filter_map(|r| r[id_col].as_str()).collect();
    let new_ids: Vec<&str> = settle_new.rows.iter().filter_map(|r| r[id_col].as_str()).collect();
    ensure!(new_ids.len() == old_ids.len() + keys.len(), "expected exactly {} new settlement rows", keys.len());
    let added: Vec<&str> = new_ids.iter().copied().filter(|k| !old_ids.contains(k)).collect();
    ensure!(added.len() == keys.len(), "settlement ids added: {added:?}");
    let mut it = settle_new.rows.iter();
    for r in &settle_old.rows {
        let mut n = it.next().context("settlement rows shorter")?;
        while added.contains(&n[id_col].as_str().unwrap_or("")) {
            n = it.next().context("settlement rows shorter")?;
        }
        ensure!(n == r, "an existing settlement row changed");
    }
    println!("campaign_map_settlements_tables: + {added:?}");
    members.insert(settle_member.to_string(), db::encode(&settle_new)?);

    // localisation.loc: existing keys are replaced in place, new ones appended
    let loc_bytes = pack_in.read(LOC_MEMBER)?;
    let (loc_version, mut entries) = db::decode_loc(&loc_bytes)?;
    ensure!(db::encode_loc(&entries, loc_version)? == loc_bytes, "localisation.loc does not round-trip byte-exact");
    let mut wanted: Vec<(String, String, u8)> = map
        .loc_rows
        .iter()
        .map(|(k, t, tip, target)| {
            assert_eq!(target, "localisation");
            (k.clone(), t.clone(), *tip)
        })
        .collect();
    for act in &activations {
        wanted.push((
            format!("start_pos_regions_rebel_faction_name_{}wld_napoleon", act.key),
            rules.regions[&act.key]["rebel_name"].as_str().context("rebel_name")?.to_string(),
            0,
        ));
    }
    let (mut replaced, mut appended) = (Vec::new(), Vec::new());
    for (key, text, tip) in wanted {
        match entries.iter_mut().find(|e| e.0 == key) {
            Some(e) => {
                replaced.push(format!("{key}: {:?} -> {text:?}", e.1));
                e.1 = text;
                e.2 = tip;
            }
            None => {
                appended.push(format!("{key} = {text:?}"));
                entries.push((key, text, tip));
            }
        }
    }
    println!("localisation.loc replaced: {replaced:#?}\nlocalisation.loc appended: {appended:#?}");
    members.insert(LOC_MEMBER.to_string(), db::encode_loc(&entries, loc_version)?);

    let pack_out = out_data.join("nap_world.pack");
    pack::write_pack(&pack_out, &members, pack_in.type_)?;

    // ---------------------------------------------------------------- 6. publish the staged map files
    for name in ["regions.esf", "poi.esf", "trade_routes.esf", THEATRE_LOOKUP] {
        copy(&work.join(name), &out_map.join(name))?;
    }
    let out_borders = out_map.join("display/borders");
    if out_borders.exists() {
        fs::remove_dir_all(&out_borders)?;
    }
    fs::create_dir_all(&out_borders)?;
    let mut border_files: Vec<String> = stats.iter().flat_map(|s| s.border_files_written.clone()).collect();
    border_files.sort();
    for f in &border_files {
        copy(&work.join("display/borders").join(f), &out_borders.join(f))?;
    }

    // ---------------------------------------------------------------- 7. re-read every output
    let p2 = Pack::open(&pack_out)?;
    ensure!(p2.entries.len() == pack_in.entries.len(), "member count changed");
    let mut changed_members = Vec::new();
    for e in &pack_in.entries {
        if p2.read(&e.name)? != pack_in.read_entry(e)? {
            changed_members.push(e.name.clone());
        }
    }
    println!("pack members changed: {changed_members:?}");
    let rt = decode_checked("regions_tables", &p2.read(regions_member)?, &schema)?;
    let sumatra_new = with_sumatra && regions_old.rows.iter().all(|r| r[key_col].as_str() != Some(SUMATRA));
    ensure!(rt.rows.len() == regions_old.rows.len() + usize::from(sumatra_new), "regions_tables row count");
    for k in keys.iter().copied() {
        let at = rt.rows.iter().position(|r| r[key_col].as_str() == Some(k)).with_context(|| format!("re-read regions_tables has no {k}"))?;
        println!("  regions_tables[{k}] = {}", row_json(&rt, at)?);
    }
    let st2 = decode_checked("campaign_map_settlements_tables", &p2.read(settle_member)?, &schema)?;
    ensure!(st2.rows.len() == settle_old.rows.len() + keys.len(), "settlement row count");
    for id in &added {
        ensure!(st2.rows.iter().any(|r| r[id_col].as_str() == Some(id)), "re-read settlements lack {id}");
    }
    let loc2 = db::parse_loc(&p2.read(LOC_MEMBER)?)?;
    let mut wanted_loc: Vec<(String, String)> = Vec::new();
    for act in &activations {
        wanted_loc.push((format!("regions_onscreen_{}", act.key), act.name.clone()));
        wanted_loc.push((format!("regions_battle_name_{}", act.key), act.settlement_name.clone()));
        wanted_loc.push((format!("start_pos_settlements_onscreen_name_{}", act.settlement_key()), act.settlement_name.clone()));
        wanted_loc.push((
            format!("start_pos_regions_rebel_faction_name_{}wld_napoleon", act.key),
            rules.regions[&act.key]["rebel_name"].as_str().unwrap().to_string(),
        ));
    }
    for (k, v) in &wanted_loc {
        let got = loc2.get(k.as_str()).map(|t| t.0.as_str());
        ensure!(got == Some(v.as_str()), "loc {k} = {got:?}, expected {v:?}");
    }
    let sp_check = esf::read(&fs::read(&startpos_out)?)?;
    ensure!(esf::write(&sp_check)? == sp_bytes, "startpos does not round-trip");
    // the start position's settlement names must resolve in the loc: collect the loc keys the new settlements use
    let rd = RegionData::parse(&esf::read(&fs::read(out_map.join("regions.esf"))?)?.root)?;
    for k in keys.iter().copied() {
        ensure!(rd.regions[rd.index(k)?].settlement.is_some(), "re-read regions.esf: {k} has no settlement");
    }
    let poi_re = esf::read(&fs::read(out_map.join("poi.esf"))?)?;
    let pois = kgc_port_editor::regionmap::poi::parse(&poi_re.root)?;
    for k in keys.iter().copied() {
        let n = pois.iter().filter(|p| p.region == k).count();
        ensure!(n > 0, "re-read poi.esf has no points of {k}");
        println!("  poi.esf: {n} points of {k}");
    }
    esf::read(&fs::read(out_map.join("trade_routes.esf"))?)?;
    ensure!(fs::read(out_map.join(THEATRE_LOOKUP))?.len() == fs::read(&exp3.join(THEATRE_LOOKUP))?.len(), "lookup TGA size changed");
    for f in &border_files {
        ensure!(!fs::read(out_borders.join(f))?.is_empty(), "empty border file {f}");
    }
    println!("re-read OK: regions.esf ({} regions), poi.esf, trade_routes.esf, {THEATRE_LOOKUP}, startpos.esf, nap_world.pack ({} members), {} border files", rd.regions.len(), p2.entries.len(), border_files.len());

    // ---------------------------------------------------------------- 8. summary
    println!("\n=== SUMMARY ===");
    for n in &notes {
        println!("{n}");
    }
    notes.clear();
    let rel = |p: &Path| p.strip_prefix(&out_data).unwrap().to_string_lossy().replace('\\', "/");
    println!("\nINSTALL (relative to the game's data folder; staged under {}):", out_data.display());
    let mut install = vec![
        "campaign_maps/nap_world/regions.esf".to_string(),
        "campaign_maps/nap_world/pathfinding.esf  (PathSynth step)".to_string(),
        "campaign_maps/nap_world/sea_grids.esf  (seagrid step)".to_string(),
        "campaign_maps/nap_world/poi.esf".to_string(),
        "campaign_maps/nap_world/trade_routes.esf".to_string(),
        format!("campaign_maps/nap_world/{THEATRE_LOOKUP}"),
        rel(&startpos_out),
        rel(&pack_out),
    ];
    install.extend(border_files.iter().map(|f| format!("campaign_maps/nap_world/display/borders/{f}")));
    for f in &install {
        println!("  {f}");
    }
    Ok(())
}
